import React, { ReactElement } from 'react';

import { Group } from '../../../series-action/components/Group.js';
import { Item } from '../../../series-action/components/Item.js';
import { SeriesBasedTooltipActionItem } from '../actions/SeriesBasedTooltipActionItem.js';

/**
 * Wraps the passed child element in a TooltipActionItem
 * or calls the function recursively if the child is a Group
 *
 * @param child - element to render
 */
export function renderActionChildren(
  child?: ReactElement,
): React.ReactNode | undefined {
  if (!child) {
    return;
  }

  return React.Children.map(child.props.children, (childItem: ReactElement) => {
    if (!childItem) {
      return;
    }
    if (childItem.type === Item) {
      return <SeriesBasedTooltipActionItem {...childItem.props} />;
    } else if (childItem.type === Group) {
      return renderActionChildren(childItem);
    }
  });
}
